breach.segment:
// Containers without a memory limit have no utilization
WHERE utilization_samples > 0
// Sample-weighted mean of the fraction of the memory limit in use over the rule window
| EVAL avg_utilization = utilization_sum / utilization_samples
// Ignore containers that stopped reporting (deleted pods) more than 5 minutes before their cluster's newest sample
| WHERE last_seen >= cluster_newest - 5 minutes
// Threshold: fraction of the memory limit (can't exceed 1.0, where the container is OOM-killed). The working set
// includes some reclaimable page cache, so cache-heavy workloads sit in the 90s; lower it for tighter warning.
// Both the window average and the latest value must reach it, so short spikes and already-restarted containers don't alert.
| WHERE avg_utilization >= 0.95 AND latest_utilization >= 0.95
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.namespace_name, resource.attributes.pod_name, resource.attributes.container_name,
       latest_utilization, avg_utilization, last_seen
| SORT latest_utilization DESC
